{
  "name": "KEL10X 直流电子负载",
  "name_en": "KEL10X DC Electronic Load",
  "manufacturer": "",
  "description": "KEL10X 是一类可编程直流电子负载，用于吸收电源、充电器、电池或电源模块输出的电能，并对被测设备进行带载测试。根据现有证据，该设备支持恒流与恒压工作模式、远端感测、面板锁定以及电压、电流、功率测量，适合实验室中的电源性能验证与基础负载测试。",
  "description_en": "The KEL10X is a programmable DC electronic load used to sink power from supplies, chargers, batteries, or power modules during load testing. Based on the available evidence, it supports constant-current and constant-voltage modes, remote sense, front-panel lock, and measurement of voltage, current, and power, making it suitable for laboratory power characterization and basic load testing.",
  "tag_hints": [
    "DC electronic load",
    "power supply testing",
    "battery discharge testing",
    "constant current mode",
    "constant voltage mode",
    "remote sense",
    "voltage current power measurement"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电子负载并进入远程控制状态。",
      "description_en": "Initialize the electronic load and place it into remote-control mode."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "设置前面板锁定状态。",
      "description_en": "Set the front-panel lock state."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量负载电流。",
      "description_en": "Measure the load current."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量负载功率。",
      "description_en": "Measure the load power."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量负载电压。",
      "description_en": "Measure the load voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "设置远端感测状态。",
      "description_en": "Set the remote-sense state."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置恒流模式下的电流设定值。",
      "description_en": "Set the current setpoint for constant-current mode."
    },
    {
      "action_name": "auto-set_cv_voltage",
      "description": "设置恒压模式下的电压设定值。",
      "description_en": "Set the voltage setpoint for constant-voltage mode."
    },
    {
      "action_name": "auto-set_mode_current",
      "description": "切换到恒流模式。",
      "description_en": "Switch to constant-current mode."
    },
    {
      "action_name": "auto-set_mode_voltage",
      "description": "切换到恒压模式。",
      "description_en": "Switch to constant-voltage mode."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭负载输入。",
      "description_en": "Enable or disable the load input."
    }
  ]
}

